# -*- coding: utf-8 -*-
from fams import *
F = 'snap'
def sc(slug, title, h1, crumb, desc, hero, answer, cards, why, steps, faq, who):
    page(slug, F, title, desc, h1, crumb, hero, answer, cards,
         [S('What usually sits behind it', ul(why)), S('What to do', ol(steps))], faq, who)

sc('snapchat-locked-after-third-party-app', 'Snapchat Locked After Using a Third-Party App',
 'Snapchat account locked after using a third-party app?', 'Locked after a third-party app',
 'Snapchat locked your account after you used a modded app or add-on? Why it happens, what to remove and how an appeal is prepared.',
 'Modified Snapchat apps and add-ons are one of the clearest reasons for a lock.',
 'Snapchat locks accounts that log in through modified apps, plug-ins or tools that change how the app works. Remove the add-on, log out everywhere, reinstall the official app from the store, and then use the unlock form once. If the lock stays, send us the message and we prepare the appeal.',
 [('Remove the tool', 'Uninstall the modified app or plug-in first.'),
  ('Use the official app', 'Reinstall it from your store.'),
  ('Use the form once', 'Extra submissions slow things down.')],
 ['A modified or unofficial Snapchat client.', 'A plug-in that saves snaps or changes the interface.', 'Login through a tool that is not Snapchat’s own.', 'Automation that sends snaps for you.'],
 ['Delete the modified app or plug-in.', 'Install the official app and log in on your usual device.', 'Open the lock message and use the unlock form once.', 'Send us the message if the lock stays.'],
 [('Can I log in through the website?', 'Often yes, but the lock applies to the account, not the app.'),
  ('Will my Memories be there?', 'They return if the account is unlocked.'),
  ('How long does a lock last?', 'It varies by the reason in the message.')],
 ['Users of modified Snapchat apps.', 'Accounts that used plug-ins.', 'People locked after installing something new.'])

sc('snapchat-locked-for-spam-activity', 'Snapchat Locked for Spam Activity',
 'Snapchat locked your account for spam activity?', 'Locked for spam activity',
 'Snapchat locked your account for spam or suspicious activity? What counts as spam, what to stop and how an appeal is prepared.',
 'Mass adds, bulk messages and repeated links are what Snapchat treats as spam.',
 'Snapchat locks accounts that add many people at once, send identical messages in bulk, or share the same link repeatedly. Stop those actions, remove any tool you use for them, and use the unlock form once. If you run a business account, explain how you use it in a sentence or two.',
 [('Stop bulk actions', 'Adds, messages and links.'),
  ('Remove tools', 'Anything that acts for you.'),
  ('Explain business use', 'Say what the account is for.')],
 ['Adding many users in a short time.', 'Sending the same message to many people.', 'Sharing the same link repeatedly.', 'Automation or scripts.'],
 ['Pause adds, bulk snaps and link sharing.', 'Remove tools and log out of other devices.', 'Use the unlock form once and be specific.', 'Send us the lock message if it persists.'],
 [('Is a business account treated differently?', 'The same rules apply. Context helps in an appeal.'),
  ('Will my friends be removed?', 'No. They stay if the account is restored.'),
  ('Can I make a second account?', 'We do not recommend it while the first is under review.')],
 ['Small businesses on Snapchat.', 'Creators who add many followers.', 'Users who used a growth tool.'])

sc('snapchat-permanently-banned-appeal', 'Snapchat Permanently Banned: What an Appeal Needs',
 'Snapchat says your account is permanently banned?', 'Permanently banned appeal',
 'Snapchat says your account is permanently banned? What this wording means, what an appeal needs and what to avoid doing meanwhile.',
 'Permanent bans are hard but not always final. The appeal needs to be specific.',
 'A permanent ban is the strictest action on a Snapchat account, but appeals are sometimes accepted when the reason was a mistake or the facts are clear. Gather the message, a short account of what you were doing, and any proof that supports it. Do not create another account to get around it, which can harm your appeal.',
 [('Read the wording', 'The message names the reason.'),
  ('Explain what happened', 'Short, factual and specific.'),
  ('Do not evade it', 'A new account can make the ban stick.')],
 ['A violation of the community guidelines.', 'Repeated earlier locks.', 'Reports from other users.', 'A device or number tied to a banned account.'],
 ['Screenshot the message and note the date.', 'Write what you were doing in a few lines.', 'Gather anything that supports your side.', 'Send it to us and we prepare the appeal.'],
 [('Is a permanent ban reversible?', 'Sometimes. We cannot promise any outcome.'),
  ('Should I use the form many times?', 'No. Send one clear appeal.'),
  ('What if my number is banned?', 'It may be tied to the account. Tell us.')],
 ['Users told the ban is permanent.', 'People who lost years of Memories.', 'Business accounts that were banned.'])

sc('snapchat-banned-after-switching-to-new-phone', 'Snapchat Banned After Switching to a New Phone',
 'Snapchat banned after you switched to a new phone?', 'Banned after a new phone',
 'Snapchat locked or banned your account after you changed phone? Why device changes raise flags and how to prepare a clean appeal.',
 'A new device and a new place at once can look like someone else logging in.',
 'Logging in from a new phone, especially with a new number or from another country, can trip a security review. Use the official app, log in once, and avoid retrying repeatedly. If the account is locked or banned, use the unlock form once and tell Snapchat you changed phones. Send us the message if it stays.',
 [('Log in once', 'Repeated attempts count against you.'),
  ('Use the official app', 'Not a modified one.'),
  ('Mention the new phone', 'It explains the new device.')],
 ['A new device, number and place all at once.', 'Too many login attempts.', 'A VPN on the new phone.', 'A phone that was previously used for a banned account.'],
 ['Turn off any VPN.', 'Log in once from the official app.', 'Use the unlock form and mention the new phone.', 'Send us the message if the lock stays.'],
 [('Could the phone itself be banned?', 'If it was used for a banned account, yes. Tell us.'),
  ('Do I need my old phone?', 'It helps with verification, if you still have it.'),
  ('Does the number matter?', 'Yes. Use the number on the account.')],
 ['People who changed phone or number.', 'Users who moved country.', 'People who bought a used phone.'])

sc('snapchat-locked-for-sexual-content-flag', 'Snapchat Locked After a Sexual Content Flag',
 'Snapchat locked your account over a sexual content flag?', 'Locked after a content flag',
 'Snapchat locked your account after a nudity or sexual content flag? How a mistaken flag can be appealed and what to include.',
 'Content flags are sometimes mistaken, and the appeal should say what the content was.',
 'If Snapchat locked your account over sexual or nudity content, read the message for the exact policy, check what you sent or shared, and be honest in your appeal. If it was a misunderstanding, such as art, health or a clothing photo, explain it plainly. Send us the message and we help you prepare the facts.',
 [('Read the exact policy', 'It tells you what the lock is about.'),
  ('Be honest', 'State what the content was.'),
  ('Keep it short', 'Long arguments do not help.')],
 ['A snap or story reported by another user.', 'Automatic image detection.', 'Content in a Spotlight or public story.', 'Earlier warnings on the account.'],
 ['Screenshot the lock message.', 'Note which content could have been flagged.', 'Write a short factual explanation.', 'Send it to us for a clear appeal.'],
 [('Can minors be involved?', 'Anything involving minors are handled very strictly. Do not appeal those without advice.'),
  ('Does deleting content help?', 'It can help future flags. It does not unlock the account.'),
  ('How long does the lock last?', 'The message states if there is a period.')],
 ['Users told the content was sexual.', 'Creators and artists.', 'Health and fitness accounts.'])

sc('snapchat-locked-no-unlock-form-available', 'Snapchat Locked With No Unlock Form Available',
 'Snapchat locked your account and there is no unlock form?', 'No unlock form available',
 'Snapchat locked your account and the unlock form is missing or fails? Why it happens and which official routes remain.',
 'Not every lock offers the form. When it is missing, a different route is needed.',
 'Some locks do not show the unlock form, or the form fails because the lock is a ban, the account is flagged for security, or the app is out of date. Update the app, try the website, and use the support form for your lock type. If none work, send us the message and we map the route that fits.',
 [('Update the app', 'An old app can hide buttons.'),
  ('Try the website', 'The same message may show a form.'),
  ('Use the right support form', 'Ban, lock and hack have different ones.')],
 ['A ban with no unlock form.', 'An outdated app.', 'A security hold after a login from a new place.', 'A form that fails due to a VPN or extension.'],
 ['Update the app and turn off any VPN.', 'Try the website on a different browser.', 'Pick the support form that matches your message.', 'Send us a screenshot if nothing works.'],
 [('Does a missing form mean a ban?', 'Often it means a ban or a security hold. The message tells.'),
  ('Can I email Snapchat?', 'Use the official support forms. Email is not a route.'),
  ('How long should I wait?', 'Wait for the period in the message, if one is given.')],
 ['Users who cannot find the unlock option.', 'Accounts with an unusual lock.', 'Anyone seeing a blank form.'])

sc('snapchat-lost-memories-after-unlock', 'Snapchat Memories Missing After Unlock',
 'Snapchat Memories missing after your account was unlocked?', 'Memories missing after unlock',
 'Snapchat Memories are missing after an unlock or a recovery? Where they usually are, what to check and what cannot be recovered.',
 'Memories often take a while to reappear, but some losses are permanent.',
 'After an unlock, Memories can take time to sync. Check the Memories tab on the official app, make sure you are logged in as the right account and that backup is on, and try a second device. If a long time passes and nothing appears, ask support to check, with screenshots. Snaps deleted before the lock may not be recoverable.',
 [('Give it time to sync', 'Open Memories on a good connection.'),
  ('Check the account', 'Wrong email or number, wrong account.'),
  ('Try a second device', 'The first may be stuck.')],
 ['A sync delay after the unlock.', 'Logged in to a different account.', 'Memories deleted before the lock.', 'Backup was off.'],
 ['Open Memories on Wi-Fi and wait.', 'Confirm the username and email are the right ones.', 'Try a second device on the official app.', 'Contact support with screenshots if still empty.'],
 [('Can Unbanz restore Memories?', 'No. Only Snapchat can. We help with the account unlock.'),
  ('What about My Eyes Only?', 'It needs your passcode. If you lost it, Memories there cannot be restored.'),
  ('Is a backup available?', 'Only if Backup was on before.')],
 ['Users unlocked after a ban.', 'People who changed phone.', 'Anyone who lost saved snaps.'])

sc('snapchat-locked-after-using-vpn', 'Snapchat Locked After Using a VPN',
 'Snapchat locked your account after using a VPN?', 'Locked after using a VPN',
 'Snapchat locked your account after logging in through a VPN or from a different country? Why it happens and how to approach the unlock.',
 'A login from a new country can trip a security hold, especially through a shared VPN address.',
 'Shared VPN addresses are used by many people at once and sometimes by bots, so Snapchat can treat a VPN login as suspicious. Turn the VPN off, log in from your usual place once, and use the unlock form once. If the lock stays, send us the message and details of where you were.',
 [('Turn off the VPN', 'Log in from your normal place.'),
  ('Do it once', 'Repeated tries make it worse.'),
  ('Say where you were', 'Context helps an appeal.')],
 ['A login from a shared VPN address.', 'A login from a new country.', 'Several attempts one after another.', 'A device not used before.'],
 ['Turn off the VPN on every device.', 'Log in once from your usual network.', 'Use the unlock form once.', 'Send us the message if it persists.'],
 [('Is every VPN a problem?', 'Not always, but shared ones are more likely to be flagged.'),
  ('Will changing my password help?', 'If you suspect a takeover, yes. Do it on a trusted network.'),
  ('Can I travel with my account?', 'Yes. Log in normally and expect the occasional check.')],
 ['Travellers and expats.', 'Users with a VPN always on.', 'People who log in at work.'])

sc('snapchat-hacked-account-locked-by-hacker', 'Snapchat Hacked Account Locked by Hacker',
 'Snapchat hacked and the hacker changed everything?', 'Hacked and changed by hacker',
 'Snapchat hacked and the email, number or password changed by someone else? The recovery routes and what to gather before you start.',
 'A hacker who changes the email and password blocks the normal reset, so the route changes.',
 'If someone changed your Snapchat email, number and password, the normal reset will not reach you. Use the official support form for a hacked account, give the username, the old email and number, and the details of what happened, and warn your friends. Send us the same information and we prepare the request.',
 [('Warn your friends', 'The hacker may message them.'),
  ('Use the hacked-account form', 'It is the right route.'),
  ('Collect the old details', 'Old email, number and device.')],
 ['A phishing page or fake login.', 'A reused password from another breach.', 'A friend’s account sending a link.', 'Login through an unofficial tool.'],
 ['Tell friends not to click links from you.', 'Gather your old email, number and device.', 'Use the hacked-account support form.', 'Send us the same information to prepare the request.'],
 [('Can I change my password if I cannot log in?', 'Only if the reset reaches you. If not, use the support form.'),
  ('Will the hacker be reported?', 'The report is about the account. We do not act against the person.'),
  ('Is there a time limit?', 'Act as soon as you can. Delays can complicate it.')],
 ['Users whose email or number changed.', 'People whose friends got scam links.', 'Accounts where the password stopped working.'])

sc('snapchat-business-account-locked', 'Snapchat Business Account Locked',
 'Snapchat business account locked or restricted?', 'Business account locked',
 'Snapchat locked a business account or its ads? Why business accounts get locked, what to gather and how an appeal is prepared.',
 'Business accounts get locked for the same reasons personal ones do, plus advertising rules.',
 'A Snapchat business account may be locked for spam, for content flags or because of an ad policy issue. Gather your business registration, your website and a short description of what the account does, and read the message for the exact policy. Use the unlock form once and send us the message for a clear appeal.',
 [('Read the exact policy', 'Spam, content or ads.'),
  ('Show the business', 'Website and registration.'),
  ('Keep the explanation short', 'What the account is for.')],
 ['Spam-like adds and messages.', 'Content flagged by another user.', 'An ad that broke a policy.', 'A login from a new device or place.'],
 ['Screenshot the message.', 'Gather the business website and registration.', 'Write what the account does in a few lines.', 'Use the unlock form, then send us the details.'],
 [('Is the ad account separate?', 'It can be. Check the notice for which one is affected.'),
  ('Can an agency appeal?', 'The owner should lead, with the agency supporting.'),
  ('Will it affect customers?', 'They may not see you while it is locked.')],
 ['Small businesses on Snapchat.', 'Agencies with client accounts.', 'Creators running a brand.'])
